#ifndef DEMODATA_H
#define DEMODATA_H

/** A file of the demo data, embedded into the executable (generated by tools/embed_demo.py from res/demo). */
struct DemoFile {
	const char* path; //relative to the data directory's `res` folder, with '/' separators
	const unsigned char* data;
	unsigned long size;
};

extern const DemoFile DEMO_FILES[];
extern const unsigned DEMO_FILE_COUNT;

#endif /* DEMODATA_H */
